package com.minecraftcodex.casino.commands;
import com.minecraftcodex.casino.Main; import org.bukkit.command.*; import org.bukkit.entity.Player; import java.util.*;
public final class CasinoCommand implements CommandExecutor,TabCompleter {private final Main plugin;public CasinoCommand(Main p){plugin=p;}public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p)){pmsg(s,"players-only");return true;}if(a.length==2 && a[0].equalsIgnoreCase("bet")){try{plugin.gui().setBet(p,Double.parseDouble(a[1]));}catch(NumberFormatException e){pmsg(p,"invalid-bet");}return true;}if(a.length!=1){pmsg(p,"unknown-game");return true;}if(!plugin.gui().open(p,a[0]))pmsg(p,"unknown-game");return true;}public List<String> onTabComplete(CommandSender s,Command c,String l,String[] a){return a.length==1?List.of("slots","blackjack","poker","roulette","truthlie","bet"):List.of();}private void pmsg(CommandSender s,String k){s.sendMessage(org.bukkit.ChatColor.translateAlternateColorCodes('&',plugin.message("prefix")+plugin.message(k)));}}
